import {runBacktest} from './backtest.mjs';
const $=s=>document.querySelector(s);let chosen=0,ranked=[];
const cities={Denver:['RiNo','Baker','Highland'],Chicago:['Logan Square','Pilsen','Wicker Park'],Atlanta:['East Atlanta Village','Old Fourth Ward','West End']};
function render(){const names=cities[$('#city').value],w=Number($('#weight').value)/100;ranked=names.map((name,i)=>({name,i,fit:[88,81,75][i],space:[56,82,91][i]})).map(x=>({...x,score:Math.round(w*x.fit+(1-w)*x.space)})).sort((a,b)=>b.score-a.score);$('#resultTitle').textContent=`Your next chapter in ${$('#city').value}.`;$('#cards').replaceChildren();$('#pins').replaceChildren();ranked.forEach((x,i)=>{const c=document.createElement('article');c.className='card'+(i===chosen?' selected':'');c.innerHTML=`<span class="rank">0${i+1}</span><div><h3>${x.name}</h3><p>Sample taste fit ${x.fit} · Sample category headroom ${x.space}</p><button class="brief-link">Open Lease Brief ↗</button></div><div class="score">${x.score}<small>DEMO INDEX</small></div>`;c.onclick=()=>{chosen=i;render()};c.querySelector('button').onclick=e=>{e.stopPropagation();brief(x)};$('#cards').append(c);const p=document.createElement('button');p.className='pin'+(i===chosen?' selected':'');p.textContent=i+1;p.style.left=[58,30,72][x.i]+'%';p.style.top=[23,58,65][x.i]+'%';p.setAttribute('aria-label',x.name);p.onclick=()=>{chosen=i;render()};$('#pins').append(p)})}
function text(tag,value,parent){const e=document.createElement(tag);e.textContent=value;parent.append(e);return e}
function brief(x){const el=$('#briefContent');el.replaceChildren();text('div','TWIN BLOCK / LEASE BRIEF',el).className='eyebrow';text('h1',x.name+', '+$('#city').value,el);text('p',$('#concept').value+' · Transfer from '+$('#origin').value,el);text('p','ILLUSTRATIVE DEMO — NOT A VALIDATED LEASING RECOMMENDATION',el).className='brief-meta';for(const [title,body] of [['Why it fits',`Sample cultural fit index: ${x.fit}/100. This placeholder demonstrates a source-to-target neighbourhood comparison. Live Qloo evidence has not been fetched.`],['Price & lease economics',`${'$'.repeat(Number($('#price').value))} target dining tier. Actual neighbourhood pricing, rents, footfall and unit economics: unverified.`],['Competitive crowding',`Illustrative category headroom: ${x.space}/100. A production result must report retrieved competitors, query radius, date and coverage limitations.`],['Three taste-matched neighbours','Pending live place retrieval. No invented business names are presented as real recommendations.'],['Before signing','Broker: validate available units, rent, permitted use and lease terms. Owner: inspect the block, confirm competitors and test actual customer demand.'],['Evidence & provenance','Source: built-in sample scenario. No live API response, acquisition date or backtest result is available.']]){const d=text('div','',el);d.className='brief-section';text('h3',title,d);text('p',body,d)}$('#brief').showModal()}
document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>{document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t===b));$('#explore').hidden=b.dataset.view!=='explore';$('#proof').hidden=b.dataset.view!=='proof';$('.intro').hidden=b.dataset.view==='proof'});$('#find').onclick=()=>{chosen=0;render()};$('#weight').oninput=()=>{$('#weightValue').textContent=$('#weight').value+'%';render()};document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{$('#concept').value=b.dataset.preset;render()});$('#closeBrief').onclick=()=>$('#brief').close();$('#printBrief').onclick=()=>window.print();$('#runProof').onclick=async()=>{try{const f=$('#benchmark').files[0];if(!f)throw Error('Choose a benchmark JSON file first.');if(f.size>2e6)throw Error('Please use a dataset under 2 MB.');const data=JSON.parse(await f.text());const r=runBacktest(data);$('#metrics').replaceChildren();$('#metrics').className='';for(const [label,value]of [['Taste ranking',r.taste.precisionAtK],['Busy-area baseline',r.busy.precisionAtK],['Seeded random mean',r.random.meanPrecisionAtK],['Plain LLM',r.llm?.precisionAtK]]){const row=text('div','',$('#metrics'));row.className='metrics-row';text('span',label,row);text('b',value===undefined?'Not supplied':(value*100).toFixed(1)+'% hits @ '+r.config.k,row)}text('p',`${r.counts.candidates} candidate cells · ${r.counts.heldOut} hidden stores · ${r.config.hitRadiusMeters} m radius`,$('#metrics'));text('p','Imported data is user-supplied and not independently verified. Provenance checks cannot establish how upstream scores were produced.',$('#metrics')).className='hint';$('#proofStatus').textContent='Evaluation complete. Scores describe the imported dataset only.'}catch(e){$('#proofStatus').textContent=e.message}};render();
